CustomField.formula:
/* priority to Priority */
Case(Priority,
	"Medium", 1000,
	"Low", 2000, 
         0
        )
+
/* priority to Milestone  */
(if (  NAS_Milestone_In_Violation__c  = True, -500, 0))
+
(if (  NAS_Milestone_Nearing_Violation__c  = True, -250, 0))
+
/* FIFO / puts anything older than 1 day at the top as Milestone approaches */
(IF ( 
((Now()-CreatedDate)*24)< 25, 
(24 - ((Now()-CreatedDate)*24)), 
0))
+
/* If on hold and follow up not due, put at end of list */
If( 
AND( 
OR( 
ispickval(Status ,"On Hold - Customer"), 
ispickval(Status ,"On Hold - Internal") 
), 
(Follow_up_Date__c > (Now() + 0.0833)) 
), 
2000, 
0 
)
+
/* If on hold and follow up due, put higher on list */
If( 
AND( 
OR( 
ispickval(Status ,"On Hold - Customer"), 
ispickval(Status ,"On Hold - Internal") 
), 
(Follow_up_Date__c < Now()) 
), 
-500, 
0 
)
+
/* Put Recurring Case at end of list */
if ($RecordType.Name = "NAS Recurring Support Case", 5000, 0)
